import express from "express";

// The canonical Express server: create an app, answer one route, listen on the port the assertions probe.
const app = express();
app.get("/", (request, response) => {
  response.type("text/plain").send("express-static-ok");
});
app.listen(3200, () => {
  console.log("listening on 3200");
});
